from contextlib import contextmanager


@contextmanager
def temporary_setting(settings, key, value):
    had_key = key in settings
    old = settings.get(key)
    settings[key] = value
    try:
        yield
    finally:
        if had_key:
            settings[key] = old
        else:
            del settings[key]

